/* A jump is a tail call: the function must not build a stack frame for it. clang-cl does not
   make a tail call of "return f(s);" by itself. The attribute makes the jump flat. */
#if defined(__clang__)
#define VU_TAIL __attribute__((musttail))
#else
#define VU_TAIL
#endif

/* The lifted path tests for a waiting interrupt before each trampoline dispatch. The kernel
   tests it at each jump target. */
static inline vu_status vu_interrupt(MotorstormVehicleState* s, uint32_t address) {
    const spu_context* ctx = s->ctx;
    if (ctx && ctx->int_enable && (*(const volatile uint32_t*)&ctx->event_status & ctx->event_mask))
        return vu_bail(s, address);
    return VU_RETURNED;
}
#define VU_INTR(address) if (vu_interrupt(s, (address)) == VU_BAIL) return VU_BAIL
/* One call. The callee comes back with the register of its return address in s->pc. The
   caller continues when the callee returned to the return address of the call. Any other
   return address continues there as an entry by address: the drain of the lifted path does
   the same. */
#define VU_CALL(call, ret) \
    { const vu_status _r = (call); if (_r != VU_RETURNED) return _r; \
      if ((s->pc & 0x3ffffu) != (ret)) { s->pc &= 0x3ffffu; VU_TAIL return vu_enter(s); } }

